const crypto = require('crypto');

function signed(body) {
  const rawBody = JSON.stringify(body);
  const timestamp = String(Math.floor(Date.now() / 1000));
  const signature = crypto
    .createHmac('sha256', $env.LENDLOOP_WEBHOOK_SECRET)
    .update(`${timestamp}.${rawBody}`)
    .digest('hex');
  return { rawBody, timestamp, signature };
}

const MESSAGE_MAX_LENGTH = 300;
const { execution, trigger, workflow } = $input.first().json;

// A failed trigger has no execution, so it also has no execution id.
const error = execution?.error ?? trigger?.error;
const executionId = execution?.id ?? `trigger-${workflow.id}-${Date.now()}`;

// Error text can quote request data, so remove emails before it leaves n8n.
const message = String(error?.message ?? 'Unknown error')
  .replace(/[^\s@]+@[^\s@]+\.[^\s@]+/g, '[email]')
  .slice(0, MESSAGE_MAX_LENGTH);

console.error(`[workflow failure] ${workflow.name} (${executionId}): ${message}`);

return [{ json: signed({
  executionId: String(executionId),
  eventType: workflow.name.includes('overdue') ? 'overdue_reminder' : 'request_notification',
  workflowName: workflow.name,
  failedNode: execution?.lastNodeExecuted,
  message,
}) }];
